"""Capture source-reviewed nighttime heavy-vehicle travel with world restoration."""
from __future__ import annotations

import hashlib
import json
import os
from pathlib import Path
from queue import Empty, Queue
import shutil
import subprocess

from restriction_measure import load_review, sha
from route_adapter import configure, step, sample, teardown

CAMERAS={'overview':(1920,1080),'approach':(1280,720),'reference_corner':(1280,720),'driver_reference':(1280,720)}


def write(path:Path,value:dict)->None:
    path.write_text(json.dumps(value,indent=2,sort_keys=True,allow_nan=False)+'\n')


def camera(world,carla,pose,name,queue):
    blueprint=world.get_blueprint_library().find('sensor.camera.rgb')
    width,height=CAMERAS[name]
    blueprint.set_attribute('image_size_x',str(width));blueprint.set_attribute('image_size_y',str(height));blueprint.set_attribute('sensor_tick','0.05')
    xyz,pyr=pose['location_xyz_m'],pose['pitch_yaw_roll_deg']
    actor=world.try_spawn_actor(blueprint,carla.Transform(carla.Location(*xyz),carla.Rotation(pitch=pyr[0],yaw=pyr[1],roll=pyr[2])))
    if actor is None:raise RuntimeError('Original night-truck camera spawn failed: '+name)
    actor.listen(lambda image:queue.put(image));return actor


def encoder(path,width,height):
    return subprocess.Popen(['ffmpeg','-hide_banner','-loglevel','error','-y','-f','rawvideo','-pixel_format','bgra','-video_size',f'{width}x{height}','-framerate','20','-i','pipe:0','-c:v','ffv1',str(path)],stdin=subprocess.PIPE,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE)


def image(queue,expected):
    try:value=queue.get(timeout=15)
    except Empty as error:raise RuntimeError('Synchronized night-truck camera frame missing') from error
    if value.frame!=expected:raise ValueError('Original camera frame identity differs')
    return value


def capture_original(root,attempt,review_path,source_root,*,host='127.0.0.1',port=2000):
    root,attempt,review_path,source_root=map(lambda x:Path(x).resolve(),(root,attempt,review_path,source_root))
    config=json.loads((root/'config.json').read_text());spec=json.loads((root/'case-spec.json').read_text());control=json.loads((root/'controller.json').read_text())
    case_id=config['selected_case_id']
    if spec.get('case_id')!=case_id:raise ValueError('Exact night truck case differs')
    if not attempt.is_dir() or any((attempt/name).exists() for name in ('trace.jsonl','video_frames.jsonl','original-night-truck-observations.json','original-night-truck-receipt.json','result.json')):
        raise ValueError('Fresh materialized Native attempt required')
    packet=load_review(review_path,source_root,case_id)
    if (packet['site']['traveled_street']['designation']!=spec['target_street_class']
            or packet['site']['district']!=spec['target_district']
            or packet['vehicle']['unladen_weight_lb']!=spec['target_unladen_lb']
            or packet['permit']['status']!=spec['target_permit_status']
            or packet['_derived_local_start'][11:16]!=spec['target_local_time']):
        raise ValueError('Reviewed night truck comparison variable differs')
    by_path={row['path']:row for row in packet['source_provenance']['files']}
    opendrive=packet.get('opendrive_source_path')
    if not opendrive or opendrive not in by_path:raise ValueError('Original OpenDRIVE source not inventoried')
    poses=packet.get('cameras',{})
    if set(poses)!=set(CAMERAS):raise ValueError('All four reviewed original camera poses required')
    for name,row in poses.items():
        if len(row.get('location_xyz_m',[]))!=3 or len(row.get('pitch_yaw_roll_deg',[]))!=3:
            raise ValueError('Original camera pose incomplete: '+name)
    shutil.copy2(review_path,attempt/'reviewed-night-truck.json')
    for source in by_path.values():
        target=attempt/'reviewed-sources'/source['path'];target.parent.mkdir(parents=True,exist_ok=True)
        shutil.copy2(source_root/source['path'],target)
    if 'SCENARIO_PIPELINE_OUTPUT_ROOT' not in os.environ:raise ValueError('Runtime output root required before Native import')
    import carla
    from worker_exchange.native_output import FrameMap,seal_capture
    from worker_exchange.world_restore import snapshot,restore
    client=carla.Client(host,int(port));client.set_timeout(30);prior=snapshot(client)
    cameras={};queues={};encoders={};handle=None;frame_map=None;failure=None;restored=False
    try:
        world=client.generate_opendrive_world((source_root/opendrive).read_text())
        live_sha=hashlib.sha256(world.get_map().to_opendrive().encode()).hexdigest()
        if live_sha!=by_path[opendrive]['sha256']:raise ValueError('Native OpenDRIVE readback differs from reviewed source')
        settings=world.get_settings();settings.synchronous_mode=True;settings.fixed_delta_seconds=.05;settings.no_rendering_mode=False;world.apply_settings(settings)
        handle=configure(world,carla,packet,float(control['target_speed_mps']))
        for name,(width,height) in CAMERAS.items():
            queues[name]=Queue();cameras[name]=camera(world,carla,poses[name],name,queues[name]);encoders[name]=encoder(attempt/(name+'.mkv'),width,height)
        frame_map=FrameMap(attempt/'video_frames.jsonl');observations=[]
        with (attempt/'trace.jsonl').open('x',buffering=1) as trace:
            for _ in range(900):
                step(handle,carla)
                frame=world.tick();time_s=float(world.get_snapshot().timestamp.elapsed_seconds)
                frame_map.append(frame,time_s)
                row=sample(world,handle,packet,frame,time_s)
                observations.append(row)
                trace.write(json.dumps({'frame':frame,'time_s':time_s,'actor_id':row['ego_actor_id'],'position_m':row['position_xy_m']},allow_nan=False)+'\n')
                for name in CAMERAS:encoders[name].stdin.write(bytes(image(queues[name],frame).raw_data))
        for process in encoders.values():
            process.stdin.close()
            if process.wait(timeout=120)!=0:raise RuntimeError('Four-view night-truck encoder failed')
        frame_map.close()
        data={'assignment_id':root.name,'case_id':case_id,'original_trace_id':'Native:'+sha(attempt/'trace.jsonl'),'diagnostic_fixture':False,
            'review_source_sha256':sha(review_path),'site':packet['site'],'vehicle':packet['vehicle'],
            'civil_clock':packet['civil_clock'],'permit':packet['permit'],'itinerary':packet['itinerary'],
            'fps':20,'frames':observations}
        write(attempt/'original-night-truck-observations.json',data)
        write(attempt/'original-night-truck-receipt.json',{'case_id':case_id,'fps':20,'frame_count':900,'diagnostic_fixture':False,'source_sha256':sha(attempt/'original-night-truck-observations.json'),'review_sha256':sha(review_path)})
    except BaseException as error:failure=error
    finally:
        if frame_map is not None and not frame_map.stream.closed:frame_map.close()
        for process in encoders.values():
            if process.poll() is None:process.kill();process.wait()
        for actor in cameras.values():
            try:actor.stop()
            finally:actor.destroy()
        if handle is not None:
            try:teardown(handle)
            except BaseException as error:failure=failure or error
        try:restored=bool(restore(client,prior)['restored'])
        except BaseException as error:failure=failure or error
    write(attempt/'native-run-status.json',{'restored':restored,'capture_complete':failure is None,'errors':[repr(failure)] if failure else []})
    if failure or not restored:raise RuntimeError('Original night-truck capture or restoration failed') from failure
    write(attempt/'acquisition-provenance.json',{'provenance_kind':'native','diagnostic_fixture':False,'case_id':case_id,'review_sha256':sha(review_path)})
    seal_capture(attempt,frames=900,restoration={'restored':True},errors=[],encoder_exit_codes={name:0 for name in CAMERAS},context={'case_id':case_id,'review_sha256':sha(review_path),'legal_verdict_claimed':False})
    return {'case_id':case_id,'frame_count':900,'restored':True,'original_source_sha256':sha(attempt/'original-night-truck-observations.json'),'physical_acceptance':False}

"""Saved-only original-source nighttime truck finalizer; no legal verdict."""
from __future__ import annotations

import argparse
import json
from pathlib import Path

from restriction_measure import load_review, measure, sha

CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
CHANNELS = ("ego_operation", "actual_unladen_weight", "local_civil_time",
            "residence_district", "street_designation", "written_permit")


def required(root: Path, name: str) -> Path:
    path = root / name
    if not path.is_file():
        raise ValueError("Missing required source: " + name)
    return path


def rows(path: Path) -> list[dict]:
    return [json.loads(line) for line in path.read_text().splitlines() if line]


def measure_weight(source: Path) -> dict:
    m = measure(source)
    return {key: m[key] for key in ("actual_unladen_weight_lb", "weight_strictly_exceeds_8000")}


def measure_time(source: Path) -> dict:
    m = measure(source)
    return {key: m[key] for key in ("local_civil_start", "local_civil_start_hhmm",
                                    "clock_uncertainty_s", "legal_time_endpoint_judgment")}


def measure_street(source: Path) -> dict:
    m = measure(source)
    return {key: m[key] for key in ("district_reviewed_as", "traveled_street_designation")}


def measure_operation(source: Path) -> dict:
    m = measure(source)
    return {key: m[key] for key in ("sample_count", "first_native_frame", "last_native_frame")}


def measure_route(source: Path) -> dict:
    return {"traveled_street_designation": measure(source)["traveled_street_designation"]}


def measure_district(source: Path) -> dict:
    return {"district_reviewed_as": measure(source)["district_reviewed_as"]}


def measure_permit(source: Path) -> dict:
    m = measure(source)
    return {key: m[key] for key in ("permit_review_status", "permit_conditions",
                                    "legal_permit_effect_judgment")}


def measure_application(source: Path) -> dict:
    packet = json.loads(Path(source).read_text())
    return {"written_application": packet["permit"].get("written_application"),
            "issued_written_permit": packet["permit"].get("issued_written_permit")}


def measure_vehicle_scope(source: Path) -> dict:
    packet = json.loads(Path(source).read_text())
    return {"vehicle_identity": packet["vehicle"]["identity"],
            "authorized_vehicle_identity": packet["permit"].get("authorized_vehicle_identity"),
            "scope_judgment": "unresolved"}


def measure_conditions(source: Path) -> dict:
    packet = json.loads(Path(source).read_text())
    return {"conditions": packet["permit"].get("conditions", []),
            "permit_review_status": packet["permit"]["status"],
            "conditions_judgment": "unresolved"}


def analyze(attempt: Path, output: Path) -> dict:
    attempt, output = Path(attempt).resolve(), Path(output).resolve()
    config = json.loads(required(attempt, "config.json").read_text())
    case_id = config["selected_case_id"]
    source = required(attempt, "original-night-truck-observations.json")
    packet = json.loads(source.read_text())
    receipt = json.loads(required(attempt, "original-night-truck-receipt.json").read_text())
    if (packet.get("case_id") != case_id or receipt.get("case_id") != case_id
            or receipt.get("source_sha256") != sha(source) or receipt.get("fps") != 20):
        raise ValueError("Original night truck receipt identity or source hash differs")
    review_path = required(attempt, "reviewed-night-truck.json")
    review = load_review(review_path, attempt / "reviewed-sources", case_id,
                         diagnostic=bool(packet.get("diagnostic_fixture")))
    if receipt.get("review_sha256") != sha(review_path) or packet.get("review_source_sha256") != sha(review_path):
        raise ValueError("Original night truck review source differs")
    for key in ("site", "vehicle", "civil_clock", "permit", "itinerary"):
        if packet.get(key) != review.get(key):
            raise ValueError("Original night truck observation context differs: " + key)
    measurement = measure(source)
    frames = packet["frames"]
    if receipt.get("frame_count") != len(frames):
        raise ValueError("Original night truck frame count differs")
    frame_map = rows(required(attempt, "video_frames.jsonl"))
    trace = rows(required(attempt, "trace.jsonl"))
    if packet.get("diagnostic_fixture") is False and packet.get("original_trace_id") != "Native:" + sha(attempt / "trace.jsonl"):
        raise ValueError("Original night truck trace source differs")
    if len(frames) != len(frame_map) or len(frames) != len(trace):
        raise ValueError("Original night truck streams differ")
    for index, (frame, mapped, row) in enumerate(zip(frames, frame_map, trace)):
        if (mapped.get("video_frame") != index or frame.get("frame") != mapped.get("carla_frame")
                or frame["frame"] != mapped.get("native_frame") or row.get("frame") != frame["frame"]
                or abs(frame["time_s"] - mapped.get("time_s", -1)) > 1e-4
                or abs(frame["time_s"] - row.get("time_s", -1)) > 1e-4):
            raise ValueError("Original night truck frame/time join differs")
    for camera in CAMERAS:
        required(attempt, camera + ".mkv")
    description = config["case"]["recording_description"]
    channels = attempt / "channels"
    channels.mkdir(exist_ok=False)
    values = {
        "ego_operation": lambda frame: {"ego_actor_id": frame["ego_actor_id"],
            "road_id": frame["road_id"], "position_xy_m": frame["position_xy_m"]},
        "actual_unladen_weight": lambda frame: {"lb": packet["vehicle"]["unladen_weight_lb"],
            "vehicle_identity": packet["vehicle"]["identity"], "source_sha256": packet["vehicle"]["weight_source_sha256"]},
        "local_civil_time": lambda frame: {"start_utc": packet["civil_clock"]["start_utc"],
            "timezone": packet["civil_clock"]["timezone"], "time_s": frame["time_s"],
            "clock_source_sha256": packet["civil_clock"]["clock_source_sha256"]},
        "residence_district": lambda frame: {"district": packet["site"]["district"],
            "frontage_reviewed": packet["site"]["frontage_reviewed"],
            "business_exclusion_reviewed": packet["site"]["business_exclusion_reviewed"]},
        "street_designation": lambda frame: {"road_id": frame["road_id"],
            "designation": frame["street_designation"],
            "source_sha256": packet["site"]["traveled_street"]["designation_source_sha256"]},
        "written_permit": lambda frame: {"status": packet["permit"]["status"],
            "issued_written_permit": packet["permit"].get("issued_written_permit"),
            "administrative_source_sha256": packet["permit"]["administrative_source_sha256"]}}
    evidence = []
    for channel in description["channels"]:
        name = channel["name"]
        if name not in values:
            raise ValueError("Unimplemented night truck channel " + name)
        reference = "channels/" + name + ".jsonl"
        with (attempt / reference).open("x") as stream:
            for frame in frames:
                stream.write(json.dumps({"time_s": frame["time_s"], "value": values[name](frame)},
                                        separators=(",", ":")) + "\n")
        evidence.append({"name": name, "unit": channel["unit"], "reference": reference})
    context = "channels/reviewed_night_truck_site.json"
    (attempt / context).write_text(json.dumps({"reviewed_night_truck_site": {
        "review_source_sha256": sha(review_path), "legal_judgment": "unresolved"}}) + "\n")
    evidence.append({"name": "reviewed_night_truck_site", "unit": "source", "reference": context})
    native = {"case_id": case_id, "measured_values": {"night_truck": measurement},
        "target_checks": [{"target": "source-bound nighttime heavy-truck operation", "requested": True,
            "measured": True, "method": "measure", "tolerance": 0, "matched": True,
            "physical_cause_confirmed": False, "cause_evidence": ["original-night-truck-observations.json"]}],
        "setup_confirmed": False, "behavior_attempted": False, "maneuver_completed": False,
        "termination_reason": "Saved night truck measurement; physical and legal review pending",
        "physical_failure_flags": [], "trace_reference": "trace.jsonl",
        "video_references": [name + ".mkv" for name in CAMERAS],
        "video_frame_map_reference": "video_frames.jsonl",
        "recording_description": description, "recording_evidence": evidence,
        "realized_observables": {}}
    (attempt / "result.json").write_text(json.dumps(native, indent=2, allow_nan=False) + "\n")
    methods = (("weight", measure_weight), ("operation", measure_operation),
               ("route", measure_route), ("district", measure_district),
               ("time", measure_time), ("application", measure_application),
               ("vehicle_scope", measure_vehicle_scope), ("conditions", measure_conditions))
    report = {"format": "worker-analysis-report", "case_id": case_id,
        "measurements": {name: {"method": method.__name__,
            "sources": {"original-night-truck-observations.json": sha(source),
                        "original-night-truck-receipt.json": sha(attempt / "original-night-truck-receipt.json"),
                        "reviewed-night-truck.json": sha(review_path)},
            "value": method(source)} for name, method in methods},
        "limitations": ["Original municipal/administrative sources and Native motion need independent review; no legal endpoint or permit verdict is claimed."]}
    output.write_text(json.dumps(report, indent=2, allow_nan=False) + "\n")
    return report


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    analyze(args.attempt, args.output)


if __name__ == "__main__":
    main()

